// Price labels.
function formatPrice(amount) {
  return amount.toFixed(2);
}
module.exports = { formatPrice };

files.src/invoiceExport.js:
// The nightly invoice export: writes yesterday's invoices to exports/invoices-<day>.csv.
function exportInvoices(invoices, day) {
  return invoices.map((i) => [day, i.id, i.total].join(',')).join('\n');
}
module.exports = { exportInvoices };

